using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.PurchaseExpense;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,Tags("PurchaseExpenseReportsController"),ApiExplorerSettings(GroupName="Purchase & Expense"),Route("api/purchase-expense/reports")]
public sealed class PurchaseExpenseReportsController(IPurchaseExpenseService s):ApiControllerBase { [HttpGet("purchase-summary"),RequirePermission("PurchaseExpense.Report",PermissionAction.View)]public async Task<IActionResult>Purchase([FromQuery]DateRangeReportQuery q,CancellationToken ct)=>FromResponse(await s.GetPurchaseSummaryAsync(q,ct));[HttpGet("supplier-outstanding"),RequirePermission("PurchaseExpense.Report",PermissionAction.View)]public async Task<IActionResult>Outstanding(CancellationToken ct)=>FromResponse(await s.GetSupplierOutstandingAsync(ct));[HttpGet("expense-summary"),RequirePermission("PurchaseExpense.Report",PermissionAction.View)]public async Task<IActionResult>Expense([FromQuery]DateRangeReportQuery q,CancellationToken ct)=>FromResponse(await s.GetExpenseSummaryAsync(q,ct));[HttpGet("category-wise-expense"),RequirePermission("PurchaseExpense.Report",PermissionAction.View)]public async Task<IActionResult>Category([FromQuery]DateRangeReportQuery q,CancellationToken ct)=>FromResponse(await s.GetCategoryWiseExpenseAsync(q,ct));[HttpGet("item-purchase-history"),RequirePermission("PurchaseExpense.Report",PermissionAction.View)]public async Task<IActionResult>Item([FromQuery]long itemId,CancellationToken ct)=>FromResponse(await s.GetItemPurchaseHistoryAsync(itemId,ct)); }
